-- voice_run_recovery(uuid)
CREATE OR REPLACE FUNCTION public.voice_run_recovery(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
